/// <summary>
/// The service class for the Planner code update batch job.
/// </summary>
class METPlannerCodeUpdService extends SysOperationServiceBase
{
    METPlannerCodeUpdateTmp metPlannerCodeUpdateTmp;

}

Method.Source:
    /// <summary>
    /// The process method of the planner code update batch job
    /// </summary>
    public void processOperation()
    {
        ReqItemTable                    reqItemTable; 
        METReqItemTable                 metreqItemTable;              
        METPlannerCodeAssignmentRules   metPlannerCodeAssignmentRulesUpdate;

        this.insertPlannerCodeWithWeight6(false);
        this.insertPlannerCodeWithWeight6(true);

        this.insertPlannerCodeWithWeight5(false);
        this.insertPlannerCodeWithWeight5(true);

        this.insertPlannerCodeWithWeight4(false);        
        this.insertPlannerCodeWithWeight4(true);

        this.insertPlannerCodeWithWeight3(false);
        this.insertPlannerCodeWithWeight3(true);

        this.insertPlannerCodeWithWeight2(false);
        this.insertPlannerCodeWithWeight2(true);

        this.insertPlannerCodeWithWeight1(false); 
        this.insertPlannerCodeWithWeight1(true);
                            
        metreqItemTable.skipDataMethods(true);
        update_recordset metreqItemTable
            setting Planner = metPlannerCodeUpdateTmp.PlannerCode
            join RecId from reqItemTable
                where reqItemTable.RecId == metreqItemTable.RefRecId
                join PlannerCode from metPlannerCodeUpdateTmp
                    where metPlannerCodeUpdateTmp.ItemId == reqItemTable.ItemId
                        && metPlannerCodeUpdateTmp.CovInventDimId == reqItemTable.CovInventDimId
                        && metPlannerCodeUpdateTmp.RuleSubSource == metreqItemTable.SubSource;

        metPlannerCodeAssignmentRulesUpdate.skipDataMethods(true);
        update_recordset metPlannerCodeAssignmentRulesUpdate
            setting RuleUsedBatchUpdate = NoYes::Yes
        join PlannerRecId from metPlannerCodeUpdateTmp
            where metPlannerCodeAssignmentRulesUpdate.RecId == metPlannerCodeUpdateTmp.PlannerRecId;

        delete_from metPlannerCodeUpdateTmp;
    }

    /// <summary>
    /// Inserts planner code for Req Item data with weight 6
    /// </summary>
    public void insertPlannerCodeWithWeight6(boolean _useBlankSiteWH)
    {
        METPlannerCodeAssignmentRules       metPlannerCodeAssignmentRules;
        ReqItemTable                        reqItemTable;
        InventItemGroupItem                 inventItemGroupItem;
        InventTable                         inventTable;
        EcoResProductCategory               ecoResProductCategory;
        InventDim                           inventDim;
        METReqItemTable                     metreqItemTable;   

        insert_recordset metPlannerCodeUpdateTmp (ItemId, CovInventDimId, PlannerCode, RuleSubSource, PlannerRecId)
        select ItemId from reqItemTable order by ItemId
            join metReqItemTable
                where metReqItemTable.RefRecId == reqItemTable.RecId
            join InventDimId from inventDim
                where inventDim.inventDimId == reqItemTable.CovInventDimId                 
            join inventTable
                where inventTable.ItemId == reqItemTable.ItemId
                join inventItemGroupItem
                    where inventItemGroupItem.ItemId           == inventTable.itemId
                        && inventItemGroupItem.ItemDataAreaId   == curExt()
                join ecoResProductCategory
                    where ecoResProductCategory.Product == inventTable.Product
                join PlannerCode, RuleSubSource, RecId from metPlannerCodeAssignmentRules
                    where metPlannerCodeAssignmentRules.RuleSubSource == metReqItemTable.SubSource
                        && metPlannerCodeAssignmentRules.RuleEnabled == NoYes::Yes

                        && ((metPlannerCodeAssignmentRules.RuleVendorSite == inventDim.InventSiteId && !_useBlankSiteWH)
                            || (metPlannerCodeAssignmentRules.RuleVendorSite == '' && _useBlankSiteWH))
                        
                        && ((metPlannerCodeAssignmentRules.RuleVendorWarehouse == inventDim.InventLocationId && !_useBlankSiteWH)
                            || (metPlannerCodeAssignmentRules.RuleVendorWarehouse == '' && _useBlankSiteWH))

                        && metPlannerCodeAssignmentRules.RuleItemGroup == inventItemGroupItem.ItemGroupId
                        && metPlannerCodeAssignmentRules.RuleProductCategory == ecoResProductCategory.Category
                        && metPlannerCodeAssignmentRules.RuleProductCategoryHierarchy == ecoResProductCategory.CategoryHierarchy
                        && metPlannerCodeAssignmentRules.RuleVendorAccount == reqItemTable.VendId
                        && metPlannerCodeAssignmentRules.RuleVendorSite == inventDim.InventSiteId
                        && metPlannerCodeAssignmentRules.RuleVendorWarehouse == inventDim.InventLocationId;       
        
    }

/// <summary> /// Inserts planner code for Req Item data with weight 5 /// </summary> public void insertPlannerCodeWithWeight5(boolean _useBlankSiteWH) { METPlannerCodeAssignmentRules metPlannerCodeAssignmentRules; ReqItemTable reqItemTable; InventItemGroupItem inventItemGroupItem; InventTable inventTable; EcoResProductCategory ecoResProductCategory; InventDim inventDim; METReqItemTable metreqItemTable; METPlannerCodeUpdateTmp metPlannerCodeUpdateTmpExist;
metPlannerCodeUpdateTmpExist.linkPhysicalTableInstance(metPlannerCodeUpdateTmp);
insert_recordset metPlannerCodeUpdateTmp (ItemId, CovInventDimId, PlannerCode, RuleSubSource, PlannerRecId) select ItemId from reqItemTable order by ItemId join metReqItemTable where metReqItemTable.RefRecId == reqItemTable.RecId join InventDimId from inventDim where inventDim.inventDimId == reqItemTable.CovInventDimId join inventTable where inventTable.ItemId == reqItemTable.ItemId join inventItemGroupItem where inventItemGroupItem.ItemId == inventTable.itemId && inventItemGroupItem.ItemDataAreaId == curExt() join ecoResProductCategory where ecoResProductCategory.Product == inventTable.Product join PlannerCode, RuleSubSource, RecId from metPlannerCodeAssignmentRules where metPlannerCodeAssignmentRules.RuleSubSource == metReqItemTable.SubSource && metPlannerCodeAssignmentRules.RuleEnabled == NoYes::Yes
&& ((metPlannerCodeAssignmentRules.RuleVendorSite == inventDim.InventSiteId && !_useBlankSiteWH) || (metPlannerCodeAssignmentRules.RuleVendorSite == '' && _useBlankSiteWH))
&& ((metPlannerCodeAssignmentRules.RuleVendorWarehouse == inventDim.InventLocationId && !_useBlankSiteWH) || (metPlannerCodeAssignmentRules.RuleVendorWarehouse == '' && _useBlankSiteWH))
&& ((metPlannerCodeAssignmentRules.RuleItemGroup == inventItemGroupItem.ItemGroupId && metPlannerCodeAssignmentRules.RuleProductCategory == ecoResProductCategory.Category && metPlannerCodeAssignmentRules.RuleProductCategoryHierarchy == ecoResProductCategory.CategoryHierarchy && metPlannerCodeAssignmentRules.RuleVendorAccount == reqItemTable.VendId && metPlannerCodeAssignmentRules.RuleVendorSite == inventDim.InventSiteId) ||
(metPlannerCodeAssignmentRules.RuleItemGroup == inventItemGroupItem.ItemGroupId && metPlannerCodeAssignmentRules.RuleProductCategory == ecoResProductCategory.Category && metPlannerCodeAssignmentRules.RuleProductCategoryHierarchy == ecoResProductCategory.CategoryHierarchy && metPlannerCodeAssignmentRules.RuleVendorSite == inventDim.InventSiteId && metPlannerCodeAssignmentRules.RuleVendorWarehouse == inventDim.InventLocationId) ||
(metPlannerCodeAssignmentRules.RuleItemGroup == inventItemGroupItem.ItemGroupId && metPlannerCodeAssignmentRules.RuleProductCategory == ecoResProductCategory.Category && metPlannerCodeAssignmentRules.RuleVendorAccount == reqItemTable.VendId && metPlannerCodeAssignmentRules.RuleVendorSite == inventDim.InventSiteId && metPlannerCodeAssignmentRules.RuleVendorWarehouse == inventDim.InventLocationId) ||
(metPlannerCodeAssignmentRules.RuleItemGroup == inventItemGroupItem.ItemGroupId && metPlannerCodeAssignmentRules.RuleProductCategoryHierarchy == ecoResProductCategory.CategoryHierarchy && metPlannerCodeAssignmentRules.RuleVendorAccount == reqItemTable.VendId && metPlannerCodeAssignmentRules.RuleVendorSite == inventDim.InventSiteId && metPlannerCodeAssignmentRules.RuleVendorWarehouse == inventDim.InventLocationId) ||
(metPlannerCodeAssignmentRules.RuleProductCategory == ecoResProductCategory.Category && metPlannerCodeAssignmentRules.RuleProductCategoryHierarchy == ecoResProductCategory.CategoryHierarchy && metPlannerCodeAssignmentRules.RuleVendorAccount == reqItemTable.VendId && metPlannerCodeAssignmentRules.RuleVendorSite == inventDim.InventSiteId && metPlannerCodeAssignmentRules.RuleVendorWarehouse == inventDim.InventLocationId)) notexists join metPlannerCodeUpdateTmpExist where metPlannerCodeUpdateTmpExist.ItemId == reqItemTable.ItemId && metPlannerCodeUpdateTmpExist.CovInventDimId == reqItemTable.CovInventDimId; }

    /// <summary>
    /// Inserts planner code for Req Item data with weight 1
    /// </summary>
    public void insertPlannerCodeWithWeight1(boolean _useBlankSiteWH)
    {
        METPlannerCodeAssignmentRules       metPlannerCodeAssignmentRules;
        ReqItemTable                        reqItemTable;
        InventItemGroupItem                 inventItemGroupItem;
        InventTable                         inventTable;
        EcoResProductCategory               ecoResProductCategory;
        InventDim                           inventDim;
        METReqItemTable                     metreqItemTable;
        METPlannerCodeUpdateTmp             metPlannerCodeUpdateTmpExist;

        metPlannerCodeUpdateTmpExist.linkPhysicalTableInstance(metPlannerCodeUpdateTmp);

        insert_recordset metPlannerCodeUpdateTmp (ItemId, CovInventDimId, PlannerCode, RuleSubSource, PlannerRecId)
        select ItemId from reqItemTable order by ItemId                
            join metReqItemTable
                where metReqItemTable.RefRecId == reqItemTable.RecId
            join InventDimId from inventDim
                where inventDim.inventDimId == reqItemTable.CovInventDimId                        
            join inventTable
                where inventTable.ItemId == reqItemTable.ItemId
                join inventItemGroupItem
                    where inventItemGroupItem.ItemId           == inventTable.itemId
                        && inventItemGroupItem.ItemDataAreaId   == curExt()
                join ecoResProductCategory
                    where ecoResProductCategory.Product == inventTable.Product
                join PlannerCode, RuleSubSource, RecId from metPlannerCodeAssignmentRules
                    where metPlannerCodeAssignmentRules.RuleSubSource == metReqItemTable.SubSource
                        && metPlannerCodeAssignmentRules.RuleEnabled == NoYes::Yes

                        && ((metPlannerCodeAssignmentRules.RuleVendorSite == inventDim.InventSiteId && !_useBlankSiteWH)
                            || (metPlannerCodeAssignmentRules.RuleVendorSite == '' && _useBlankSiteWH))
                        && ((metPlannerCodeAssignmentRules.RuleVendorWarehouse == inventDim.InventLocationId && !_useBlankSiteWH)
                            || (metPlannerCodeAssignmentRules.RuleVendorWarehouse == '' && _useBlankSiteWH))
                                
                        && (metPlannerCodeAssignmentRules.RuleItemGroup == inventItemGroupItem.ItemGroupId
                        || metPlannerCodeAssignmentRules.RuleProductCategory == ecoResProductCategory.Category
                        || metPlannerCodeAssignmentRules.RuleProductCategoryHierarchy == ecoResProductCategory.CategoryHierarchy
                        || metPlannerCodeAssignmentRules.RuleVendorAccount == reqItemTable.VendId
                        || metPlannerCodeAssignmentRules.RuleVendorSite == inventDim.InventSiteId
                        || metPlannerCodeAssignmentRules.RuleVendorWarehouse == inventDim.InventLocationId)
            
            notexists join metPlannerCodeUpdateTmpExist
                where metPlannerCodeUpdateTmpExist.ItemId == reqItemTable.ItemId
                    && metPlannerCodeUpdateTmpExist.CovInventDimId == reqItemTable.CovInventDimId;
    }
